    "description": "Elevate Your Home with the SMART LIGHT SWITCH\n\nThe SMART LIGHT SWITCH is your key to a modern, connected, and convenient home. Designed with a sleek 2.5D glass panel and a concave button design, this sophisticated switch combines aesthetics with cutting-edge technology, enabling you to control your home’s lighting effortlessly.\n\nFeature-Rich Design for Maximum Convenience\n\nEquipped with status memory and backlight on/off functionality, the SMART LIGHT SWITCH ensures you never lose your desired settings even after a power outage. The system operates seamlessly across multiple voltages (110-240V AC/50Hz~60Hz) and includes models with multiple gang options (1, 2, 3, 4, 5, or 6 gang), accommodating different home layouts. Its optimized design supports a rated load of Connectivity and Smart Integration\n\nMake your home smarter with this innovative light switch’s integration capabilities. Featuring the advanced 802.1lb/g/n transmission protocol, the SMART LIGHT SWITCH works flawlessly with WIFI 2.4GHz and Bluetooth. Plus, it’s compatible with Google Home, granting you hands-free voice control for ultimate convenience.\n\nProduct Specifications at a Glance\n\nThe SMART LIGHT SWITCH stands out with its compact size of 120x72x33 MM and an elegant glass frame. Whether you need it for a single light or multiple connections, the switch delivers the perfect solution for modern smart home setups.\n\nTransform your living space today with the SMART LIGHT SWITCH – the perfect blend of style, technology, and functionality!",
